CREATE TABLE Projects(ProjectId nvarchar(80) PRIMARY KEY,Code nvarchar(40),Name nvarchar(200),Client nvarchar(200),Status nvarchar(30),BudgetHours decimal(18,2),HourlyRate decimal(18,2));CREATE TABLE Employees(EmployeeId nvarchar(80) PRIMARY KEY,Name nvarchar(200),Email nvarchar(320),Active bit);CREATE TABLE TimeEntries(EntryId nvarchar(80) PRIMARY KEY,ProjectId nvarchar(80),EmployeeId nvarchar(80),WorkDate date,StartTime time,EndTime time,Hours decimal(18,2),Activity nvarchar(200),Description nvarchar(max),Billable bit,Invoiced bit,InvoiceDate date,InvoiceReference nvarchar(100));GO
CREATE VIEW vwPowerBIProjectHours AS SELECT t.*,p.Code ProjectCode,p.Name ProjectName,p.Client,p.HourlyRate,t.Hours*p.HourlyRate Amount,e.Name EmployeeName,e.Email EmployeeEmail FROM TimeEntries t JOIN Projects p ON p.ProjectId=t.ProjectId JOIN Employees e ON e.EmployeeId=t.EmployeeId;GO
